messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// --- Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB); // Sky blue
scene.fog = new THREE.Fog(0x87CEEB, 50, 200);

const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(-8, 6, 15);
camera.lookAt(0, 0, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(10, 20, 10);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
scene.add(dirLight);

// --- Ground ---
const groundGeo = new THREE.PlaneGeometry(200, 60);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a7d3a });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.1;
ground.receiveShadow = true;
scene.add(ground);

// --- Track ---
const trackGeo = new THREE.PlaneGeometry(12, 100);
const trackMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
const track = new THREE.Mesh(trackGeo, trackMat);
track.rotation.x = -Math.PI / 2;
track.position.y = 0;
track.receiveShadow = true;
scene.add(track);

// Track lines
for (let i = -45; i <= 45; i += 5) {
    const lineGeo = new THREE.PlaneGeometry(0.3, 2);
    const lineMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const line = new THREE.Mesh(lineGeo, lineMat);
    line.rotation.x = -Math.PI / 2;
    line.position.set(0, 0.01, i);
    scene.add(line);
}

// --- Finish Line ---
const finishGeo = new THREE.PlaneGeometry(12, 2);
const finishMat = new THREE.MeshStandardMaterial({ 
    color: 0xffffff,
    map: createCheckerTexture()
});
const finish = new THREE.Mesh(finishGeo, finishMat);
finish.rotation.x = -Math.PI / 2;
finish.position.set(0, 0.02, 35);
scene.add(finish);

// Finish line posts
const postGeo = new THREE.BoxGeometry(0.5, 4, 0.5);
const postMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
const post1 = new THREE.Mesh(postGeo, postMat);
post1.position.set(-6, 2, 35);
scene.add(post1);
const post2 = new THREE.Mesh(postGeo, postMat);
post2.position.set(6, 2, 35);
scene.add(post2);

// Banner
const bannerGeo = new THREE.BoxGeometry(12.5, 1.5, 0.3);
const bannerMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
const banner = new THREE.Mesh(bannerGeo, bannerMat);
banner.position.set(0, 4.5, 35);
scene.add(banner);

function createCheckerTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 128;
    canvas.height = 32;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, 128, 32);
    for (let i = 0; i < 8; i++) {
        for (let j = 0; j < 2; j++) {
            ctx.fillStyle = '#fff';
            ctx.fillRect(i * 16, j * 16, 16, 16);
        }
    }
    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    return texture;
}

// --- Car Builder ---
function buildCar(color, laneZ) {
    const carGroup = new THREE.Group();

    // Body
    const bodyGeo = new THREE.BoxGeometry(2.2, 0.8, 4.5);
    const bodyMat = new THREE.MeshStandardMaterial({ 
        color: color,
        metalness: 0.6,
        roughness: 0.3
    });
    const body = new THREE.Mesh(bodyGeo, bodyMat);
    body.position.y = 0.6;
    body.castShadow = true;
    carGroup.add(body);

    // Roof / Cabin
    const roofGeo = new THREE.BoxGeometry(1.8, 0.6, 2);
    const roofMat = new THREE.MeshStandardMaterial({ 
        color: 0x333333,
        metalness: 0.3,
        roughness: 0.5
    });
    const roof = new THREE.Mesh(roofGeo, roofMat);
    roof.position.set(0, 1.3, -0.3);
    roof.castShadow = true;
    carGroup.add(roof);

    // Wheels
    const wheelGeo = new THREE.CylinderGeometry(0.35, 0.35, 0.3, 16);
    const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
    const positions = [
        [-1.1, 0.35, 1.5],
        [1.1, 0.35, 1.5],
        [-1.1, 0.35, -1.5],
        [1.1, 0.35, -1.5]
    ];
    positions.forEach(pos => {
        const wheel = new THREE.Mesh(wheelGeo, wheelMat);
        wheel.position.set(...pos);
        wheel.rotation.z = Math.PI / 2;
        wheel.castShadow = true;
        carGroup.add(wheel);
    });

    // Headlights
    const lightGeo = new THREE.SphereGeometry(0.2, 8, 8);
    const lightMat = new THREE.MeshStandardMaterial({ color: 0xffffaa, emissive: 0xffffaa, emissiveIntensity: 0.5 });
    const light1 = new THREE.Mesh(lightGeo, lightMat);
    light1.position.set(-0.7, 0.6, 2.3);
    carGroup.add(light1);
    const light2 = new THREE.Mesh(lightGeo, lightMat);
    light2.position.set(0.7, 0.6, 2.3);
    carGroup.add(light2);

    // Tail lights
    const tailGeo = new THREE.BoxGeometry(0.4, 0.2, 0.1);
    const tailMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 0.3 });
    const tail1 = new THREE.Mesh(tailGeo, tailMat);
    tail1.position.set(-0.8, 0.6, -2.25);
    carGroup.add(tail1);
    const tail2 = new THREE.Mesh(tailGeo, tailMat);
    tail2.position.set(0.8, 0.6, -2.25);
    carGroup.add(tail2);

    carGroup.position.set(0, 0, laneZ);
    return carGroup;
}

// --- Create Cars ---
const redCar = buildCar(0xff0000, -2);
const blueCar = buildCar(0x0066ff, 2);
scene.add(redCar);
scene.add(blueCar);

// --- Race Logic ---
let raceTime = 0;
const raceDuration = 6; // seconds per race
const finishLineZ = 35;
const startZ = -30;

function getRedCarPosition(t) {
    // Red car starts slower, then accelerates and overtakes
    const progress = t / raceDuration;
    let z;
    if (progress < 0.3) {
        // Slow start
        z = startZ + (finishLineZ - startZ) * (progress / 0.3) * 0.55;
    } else if (progress < 0.6) {
        // Accelerating, overtaking blue car
        const subProgress = (progress - 0.3) / 0.3;
        z = startZ + (finishLineZ - startZ) * (0.55 + subProgress * 0.35);
    } else {
        // Final stretch, winning
        const subProgress = (progress - 0.6) / 0.4;
        z = startZ + (finishLineZ - startZ) * (0.90 + subProgress * 0.10);
    }
    return z;
}

function getBlueCarPosition(t) {
    // Blue car leads early, then falls behind
    const progress = t / raceDuration;
    let z;
    if (progress < 0.3) {
        // Leading
        z = startZ + (finishLineZ - startZ) * (progress / 0.3) * 0.65;
    } else if (progress < 0.6) {
        // Maintaining but getting passed
        const subProgress = (progress - 0.3) / 0.3;
        z = startZ + (finishLineZ - startZ) * (0.65 + subProgress * 0.20);
    } else {
        // Final stretch, losing
        const subProgress = (progress - 0.6) / 0.4;
        z = startZ + (finishLineZ - startZ) * (0.85 + subProgress * 0.10);
    }
    return z;
}

// --- Animation Loop ---
let lastTime = performance.now();

function animate() {
    requestAnimationFrame(animate);

    const now = performance.now();
    const delta = (now - lastTime) / 1000;
    lastTime = now;

    raceTime += delta;

    if (raceTime >= raceDuration) {
        // Reset
        raceTime = 0;
    }

    // Update positions
    const redZ = getRedCarPosition(raceTime);
    const blueZ = getBlueCarPosition(raceTime);

    redCar.position.z = redZ;
    blueCar.position.z = blueZ;

    // Rotate wheels
    const wheelSpeed = 10;
    redCar.children.forEach(child => {
        if (child.geometry.type === 'CylinderGeometry') {
            child.rotation.x += delta * wheelSpeed;
        }
    });
    blueCar.children.forEach(child => {
        if (child.geometry.type === 'CylinderGeometry') {
            child.rotation.x += delta * wheelSpeed;
        }
    });

    // Camera follows the action
    const midZ = (redZ + blueZ) / 2;
    camera.position.z = midZ - 12;
    camera.position.x = -6;
    camera.position.y = 5;
    camera.lookAt(0, 0, midZ);

    renderer.render(scene, camera);
}

// --- Resize Handler ---
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start
animate();

</script>
</body>
</html>
```
